pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != recipient);
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(0));

        // Deploy an intermediate contract that will call withdrawAll on behalf of the fuzzed caller
        Proxy proxy = new Proxy();

        // Fund the contract with Ether
        vm.deal(address(c), amount);

        // Caller calls the proxy which forwards to c.withdrawAll
        vm.prank(caller);
        proxy.forward(address(c), recipient);

        // The reference (owner == msg.sender) should revert for non-owner caller, leaving balance unchanged
        // The buggy (tx.origin == msg.sender) allows the drain, balance becomes zero
        bool refBalanceZero = address(c).balance == 0;
        bool ownerIsCaller = c.owner() == caller;

        // Universal property: If the contract balance is zero after the call,
        // then the caller must be the owner.
        // In reference: always holds (reverts for non-owner, so balance stays >0, implication vacuously true)
        // In mutant: broken when non-owner caller uses proxy (tx.origin == caller == caller, msg.sender == proxy)
        //              then balance becomes zero even though caller != owner.
        assertTrue(!refBalanceZero || ownerIsCaller);
    }
}

